import { render } from '@testing-library/react';
import React from 'react';
import { ProgressTracker } from '../../../../../..';

describe('Step', () => {
  it('should be shown a console warn when the ProgressTracker.Step is called outside a ProgressTracker.Header and ProgressTracker.Root component', () => {
    jest.spyOn(console, 'warn').mockImplementation();
    render(<ProgressTracker.Step index={0} />);
    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining(
        'Make sure of ProgressTracler.Step component is subcomponent of ProgressTracker.Header and ProgressTracker.Root.'
      )
    );
  });
});
